export type AuthStatus = {
	loggedIn: boolean,
	login: string | null,
	/**
	 *  gh-student's scopes the token lacks (`gh auth refresh` adds them). Empty when it
	 *  can't be told: offline, or a token without classic scopes (fine-grained, app).
	 */
	missingScopes: string[],
	/**
	 *  gh is using a token from this environment variable. gh can't store, switch or
	 *  widen a login then, so the app doesn't offer to.
	 */
	envToken: string | null,
};

/**  A branch with commits that aren't on the default branch. */
export type Branch = {
	name: string,
	commits: number,
};

/**  How the running app was installed, which decides what updating can do. */
export type Bundle = 
/**  macOS `.app` (from the dmg). */
"app" | "msi" | "nsis" | "appImage" | "deb" | "rpm" | 
/**  Not installed from a bundle (built from source, a bare binary): no self-update. */
"unbundled";

/**
 *  The words of the event notes, from the UI's i18n (`set_calendar_labels`), so Rust writes
 *  no English of its own. `{name}`, `{n}`, `{score}` and `{max}` are filled in.
 */
export type CalendarLabels = {
	class: string,
	group: string,
	groupNumber: string,
	graded: string,
	submitted: string,
	notAccepted: string,
};

/**
 *  A classroom the student belongs to. Read from the description of its secret student
 *  team (`classroom-team-v1`), which exists so members can enumerate their classrooms
 *  without access to the private config repo.
 */
export type Classroom = {
	org: string,
	slug: string,
	name: string | null,
	term: string | null,
	/**  `false` once the teacher archived the classroom. */
	active: boolean,
	secret: string | null,
	/**  Custom Pages host for orgs off `github.io`. */
	pagesBaseUrl: string | null,
};

