export type Network = "normal" | 
/**  GitHub answers every request with a server error; the network itself works. */
"githubDown" | 
/**  Nothing answers: requests fail to connect, the probe too. */
"noInternet";

/**  A notification for the UI to word. */
export type Notice = { kind: "due"; assignment: string; due: string } | { kind: "grade"; assignment: string; score: number; maxScore: number } | 
/**  The autograder couldn't grade the last push (not failing tests: those are a grade). */
{ kind: "gradingFailed"; assignment: string } | { kind: "feedback"; assignment: string; count: number } | { kind: "newAssignment"; assignment: string; classroom: string } | { kind: "teammatePush"; assignment: string; author: string } | 
/**  Classmates joined the user's group (names, else logins). */
{ kind: "groupJoined"; assignment: string; members: string[] } | 
/**  `due` is `None` when the deadline was removed. */
{ kind: "deadlineChanged"; assignment: string; due: string | null } | { kind: "closed"; assignment: string } | 
/**  A new version of the app is downloaded and installs on restart (`updater.rs`). */
{ kind: "updateReady"; version: string };

export type Os = "macos" | "windows" | "linux";

/**  The most pressing reason the graded state lags behind the student's work. */
export type Pending = 
/**
 *  Someone pushed commits the clone doesn't have while it holds uncommitted or
 *  unpushed work: pull now, before the two diverge further.
 */
"conflict" | "uncommitted" | "unpushed" | 
/**
 *  A branch, local or pushed, holds commits that aren't on the default branch, which
 *  is what gets graded.
 */
"unmerged" | 
/**  Tag-mode assignment whose pushed head has no `submit/*` tag. */
"unsubmitted";

export type Phase = 
/**  Pages of the repo list, plus the teams query. */
"listing" | 
/**  `.classroom50.yaml` batches for repos pushed since the last sync, and group members. */
"details" | 
/**  Each classroom's `assignments.json`. */
"manifests" | 
/**  Status batches of the assignment repos. */
"statuses" | 
/**  Folders scanned for clones. */
"scan" | 
/**  `git status` and the comparison with GitHub of each clone. */
"clones";

/**  What a phase cost in the last run of a kind of sync. */
export type PhaseCost = {
	seconds: number,
	steps: number,
};

