export type ToolStatus = {
	tool: Tool,
	installed: boolean,
	version: string | null,
	/**
	 *  Installed, but older than the app needs (`MIN_GH`, `MIN_GH_STUDENT`): installing gh
	 *  again upgrades it, gh-student is upgraded. A version that can't be read isn't.
	 */
	outdated: boolean,
};

/**
 *  The menu's words, from the UI's i18n (`set_tray_labels`), sent at startup and when the
 *  language changes.
 */
export type TrayLabels = {
	open: string,
	quit: string,
};

/**  What the UI knows and Rust doesn't. */
export type UiFacts = {
	/**  `__COMMIT__`, the commit the frontend was built from. */
	commit: string | null,
	/**  The `data-os` skin in use (a dev build may preview another OS's). */
	skin: string,
	/**  The catalog in use (`en`, `fr`...). */
	locale: string,
};

export type Unaccepted = Unaccepted_Serialize | Unaccepted_Deserialize;

export type Unaccepted_Deserialize = {
	/**  `org/classroom/assignment`, lowercase. */
	id: string,
	classroom: Classroom,
	assignment: Assignment_Deserialize,
	acceptUrl: string,
	/**  The group the user is already on (a teacher-formed group, or one they joined). */
	group: Group | null,
};

export type Unaccepted_Serialize = {
	/**  `org/classroom/assignment`, lowercase. */
	id: string,
	classroom: Classroom,
	assignment: Assignment_Serialize,
	acceptUrl: string,
	/**  The group the user is already on (a teacher-formed group, or one they joined). */
	group: Group | null,
};

/**  Releases the app updates to: published stable ones, or also pre-releases. */
export type UpdateChannel = "stable" | "beta";

export type UpdateState = { phase: "idle" } | { phase: "checking" } | { phase: "downloading"; version: string; downloaded: number; 
/**  `None` when the server sent no length: the bar is indeterminate. */
total: number | null } | { phase: "ready"; version: string; notes: string | null } | 
/**  The last check the user started, or the last download, failed. */
{ phase: "error"; error: Failure };

/**  What `update-state` carries and `update_status` returns. */
export type UpdateStatus = {
	state: UpdateState,
	/**  "Later" was chosen: the banner stays, without the question. */
	deferred: boolean,
	/**  "Restart now" is running. */
	installing: boolean,
	/**  The dev build's fake update (`simulate_update`): Restart only logs. */
	simulated: boolean,
	lastCheck: string | null,
	bundle: Bundle,
	canUpdate: boolean,
	installOnQuit: boolean,
	asksPassword: boolean,
	hasBeta: boolean,
};

